import{_ as e,o as a,c as s,a as n}from"./app.CYXXef1p.js";const h=JSON.parse('{"title":"Pareto Frontier Matrix: Model Selection Guide","description":"","frontmatter":{},"headers":[],"relativePath":"reference/PARETO_FRONTIER_MATRIX.md","filePath":"reference/PARETO_FRONTIER_MATRIX.md","lastUpdated":1771753292000}'),r={name:"reference/PARETO_FRONTIER_MATRIX.md"};function i(d,t,o,l,c,p){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="pareto-frontier-matrix-model-selection-guide" tabindex="-1">Pareto Frontier Matrix: Model Selection Guide <a class="header-anchor" href="#pareto-frontier-matrix-model-selection-guide" aria-label="Permalink to &quot;Pareto Frontier Matrix: Model Selection Guide&quot;">​</a></h1><p><strong>Purpose:</strong> Single-page reference for selecting AI models based on performance, cost, and speed constraints.</p><p><strong>Last Updated:</strong> 2026-02-15 <strong>Context:</strong> User&#39;s current spend ~$550/mo across Claude, Cursor, Gemini, and others. Goal: optimize cost/quality ratio while meeting SLA constraints.</p><hr><h2 id="table-1-performance-tiers" tabindex="-1">Table 1: Performance Tiers <a class="header-anchor" href="#table-1-performance-tiers" aria-label="Permalink to &quot;Table 1: Performance Tiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Performance Tier</th><th>Benchmark Threshold</th><th>Models Meeting Threshold</th><th>Use Cases</th></tr></thead><tbody><tr><td><strong>Excellent (78%+)</strong></td><td>SWE-Bench ≥ 78% OR AIME ≥ 90%</td><td>Claude Opus 4.6 (80.8%), Gemini 3 Flash (78%), MiniMax M2.5 (80.2%), GLM-5 (92.7% AIME)</td><td>Complex reasoning, architecture design, multi-step debugging, novel problem-solving</td></tr><tr><td><strong>Good (75-78%)</strong></td><td>SWE-Bench 75-78%</td><td>Claude Sonnet 4.5 (77.2%)</td><td>Standard implementations, code generation, refactoring, integration tasks</td></tr><tr><td><strong>Acceptable (70-75%)</strong></td><td>SWE-Bench 70-75%</td><td>Claude Haiku 4.5 (73.3%), GPT-5.3-Codex (56.8% SPro)</td><td>Quick fixes, snippets, simple queries, well-defined tasks</td></tr><tr><td><strong>Budget (65-70%)</strong></td><td>SWE-Bench &lt;70%</td><td>GLM 4.7 (74%), Minimax M2 (70%), GPT-4o mini (70%)</td><td>Simple coding when quality floor is met but cost is critical, utility tasks</td></tr></tbody></table><hr><h2 id="table-2-speed-tiers-base-minima-in-milliseconds" tabindex="-1">Table 2: Speed Tiers (Base Minima in Milliseconds) <a class="header-anchor" href="#table-2-speed-tiers-base-minima-in-milliseconds" aria-label="Permalink to &quot;Table 2: Speed Tiers (Base Minima in Milliseconds)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Speed SLA</th><th>P50 Latency</th><th>P99 Latency</th><th>Models</th><th>Use Case</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Instant (&lt;1s)</strong></td><td>&lt;300ms</td><td>&lt;800ms</td><td>Gemini Flash (150-600ms), GPT-4o mini (200-800ms), GLM Flash (150-600ms)</td><td>Interactive (REPL, chat, live code completion)</td><td>Prioritize for user-facing tasks</td></tr><tr><td><strong>Fast (&lt;5s)</strong></td><td>300-500ms</td><td>800-1500ms</td><td>Claude Haiku (300-1200ms), Cursor Ultra (400-1500ms)</td><td>Standard request (CLI, editor, background ops)</td><td>Acceptable for most workflows</td></tr><tr><td><strong>Normal (&lt;20s)</strong></td><td>500-1000ms</td><td>1500-3000ms</td><td>Claude Sonnet (400-1500ms), Gemini 2.5 Pro (250-900ms)</td><td>Engineering tasks, analysis, multi-step workflows</td><td>Batch processing OK</td></tr><tr><td><strong>Batch (&lt;60s)</strong></td><td>1000ms+</td><td>3000ms+</td><td>Claude Opus (1760ms+), MiniMax reasoning modes</td><td>Offline, batch processing, comprehensive analysis</td><td>No time pressure</td></tr></tbody></table><hr><h2 id="table-3-cost-tiers-effective-per-m-tokens-including-tax" tabindex="-1">Table 3: Cost Tiers (Effective Per M Tokens, Including Tax) <a class="header-anchor" href="#table-3-cost-tiers-effective-per-m-tokens-including-tax" aria-label="Permalink to &quot;Table 3: Cost Tiers (Effective Per M Tokens, Including Tax)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cost Tier</th><th>Per-M Cost</th><th>Annual Cost (@50M tokens)</th><th>Models</th><th>Budget Profile</th></tr></thead><tbody><tr><td><strong>Ultra-Low (&lt;$1/M)</strong></td><td>$0.27-0.79</td><td>$13.50-39.50</td><td>GLM Flash ($0.27), Minimax M2 ($0.79), GPT-4o mini ($0.375)</td><td>Ultra high-volume loops (10K+ requests/mo), acceptable 65-70% quality</td></tr><tr><td><strong>Low ($1-4/M)</strong></td><td>$1-4</td><td>$50-200</td><td>Claude Haiku ($3.50), Gemini 2.5 Pro (&lt;200K tokens) ($4.07)</td><td>High-volume (1K-10K requests/mo), baseline quality 70%+</td></tr><tr><td><strong>Standard ($4-12/M)</strong></td><td>$4-12</td><td>$200-600</td><td>Claude Sonnet ($10.50), OpenAI GPT-4o ($10.00), Gemini 3 Pro ($10.00)</td><td>Typical use (100-1K requests/mo), quality 75%+</td></tr><tr><td><strong>Premium ($15+/M)</strong></td><td>$15+</td><td>$750+</td><td>Claude Opus ($17.50)</td><td>Selective, high-stakes tasks (&lt;100 requests/mo), 80%+ quality required</td></tr></tbody></table><hr><h2 id="table-4-pareto-frontier-—-6-model-recommendation-tier" tabindex="-1">Table 4: Pareto Frontier — 6-Model Recommendation Tier <a class="header-anchor" href="#table-4-pareto-frontier-—-6-model-recommendation-tier" aria-label="Permalink to &quot;Table 4: Pareto Frontier — 6-Model Recommendation Tier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rank</th><th>Provider/Model</th><th>Cost/M</th><th>Quality</th><th>Speed (P50)</th><th>Best For</th><th>Constraint Profile</th></tr></thead><tbody><tr><td>🥇 <strong>BEST</strong></td><td>Claude Haiku 4.5</td><td>$3.50</td><td>73% (Good)</td><td>300-1200ms</td><td><strong>High-volume NORMAL tasks, cost-conscious</strong></td><td>Cost &lt; $0.05/call, Speed &gt; 5s SLA, Perf ≥ 70%</td></tr><tr><td>🥈 <strong>FASTEST</strong></td><td>Gemini 3 Flash</td><td>$1.50-3.00</td><td>78% (Excellent)</td><td>150-600ms</td><td><strong>FAST queries, latency-critical, interactive</strong></td><td>Cost &lt; $0.01/call, Speed &gt; 1s SLA, Perf ≥ 75%</td></tr><tr><td>🥉 <strong>BALANCED</strong></td><td>Claude Sonnet 4.5</td><td>$10.50</td><td>77% (Excellent)</td><td>400-1500ms</td><td><strong>COMPLEX reasoning, standard tier, debugging</strong></td><td>Cost &lt; $0.10/call, Speed &gt; 20s SLA, Perf ≥ 75%</td></tr><tr><td>4️⃣ <strong>PEAK</strong></td><td>Claude Opus 4.6</td><td>$17.50</td><td>81% (Excellent)</td><td>1760ms+</td><td><strong>HIGH_COMPLEX, mission-critical, architecture</strong></td><td>Cost &lt; $0.50/call, Speed &gt; 60s SLA, Perf ≥ 80%</td></tr><tr><td>5️⃣ <strong>ULTRA-BUDGET</strong></td><td>Minimax M2.5</td><td>$0.79</td><td>80% (Excellent)</td><td>Very fast</td><td><strong>Agentic loops, ultra-high-volume batch</strong></td><td>Cost &lt; $0.005/call, Speed &gt; 10s SLA, Perf ≥ 75%</td></tr><tr><td>6️⃣ <strong>FALLBACK</strong></td><td>GPT-4o mini</td><td>$0.375</td><td>70% (Acceptable)</td><td>200-800ms</td><td><strong>Ultra-low-cost fallback, simple tasks, emergency</strong></td><td>Cost &lt; $0.003/call, Speed &gt; 1s SLA, Perf ≥ 70%</td></tr></tbody></table><p><strong>Annotation:</strong></p><ul><li><strong>🥇 Claude Haiku 4.5</strong> dominates the &quot;Good enough + affordable + reliable&quot; segment. Recommended as primary for 80% of use cases.</li><li><strong>🥈 Gemini 3 Flash</strong> is fastest and near-excellent quality; ideal for interactive/latency-critical paths.</li><li><strong>🥉 Claude Sonnet 4.5</strong> steps up for complex multi-step reasoning; 75% quality jump over Haiku for 3x cost.</li><li><strong>🥇 Claude Opus 4.6</strong> reserved for hardest problems (&gt;15K token context, architecture decisions).</li><li><strong>5️⃣ Minimax M2.5</strong> is the &quot;dark horse&quot; — frontier-level quality at ultra-low cost, but less proven in production.</li><li><strong>6️⃣ GPT-4o mini</strong> is emergency fallback and last-mile option when budget is absolutely critical.</li></ul><hr><h2 id="table-5-cost-quality-ratio-quality-per-dollar-spent" tabindex="-1">Table 5: Cost-Quality Ratio (Quality per Dollar Spent) <a class="header-anchor" href="#table-5-cost-quality-ratio-quality-per-dollar-spent" aria-label="Permalink to &quot;Table 5: Cost-Quality Ratio (Quality per Dollar Spent)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Cost/M</th><th>Quality %</th><th>Ratio (Quality/$)</th><th>Recommendation</th></tr></thead><tbody><tr><td>Claude Haiku 4.5</td><td>$3.50</td><td>73</td><td><strong>20.9</strong></td><td>⭐⭐⭐⭐⭐ BEST ratio; default tier</td></tr><tr><td>Gemini 3 Flash</td><td>$2.00 (avg)</td><td>78</td><td><strong>39.0</strong></td><td>⭐⭐⭐⭐⭐ Superior if cost available</td></tr><tr><td>Claude Sonnet 4.5</td><td>$10.50</td><td>77</td><td><strong>7.3</strong></td><td>⭐⭐⭐ Good for complex tasks</td></tr><tr><td>Claude Opus 4.6</td><td>$17.50</td><td>81</td><td><strong>4.6</strong></td><td>⭐⭐ Use sparingly for hardest 5%</td></tr><tr><td>Minimax M2.5</td><td>$0.79</td><td>80</td><td><strong>101.3</strong></td><td>⭐⭐⭐⭐ Best raw ratio; scaling option</td></tr><tr><td>GPT-4o mini</td><td>$0.375</td><td>70</td><td><strong>186.7</strong></td><td>⭐ Emergency fallback only</td></tr></tbody></table><p><strong>Key Insight:</strong> Gemini Flash has the best ratio when cost is available; Minimax M2.5 is exceptional for batch/agentic loops; Claude Haiku is the &quot;Goldilocks&quot; option (cost-reasonable + quality-solid + proven in production).</p><hr><h2 id="selection-decision-tree" tabindex="-1">Selection Decision Tree <a class="header-anchor" href="#selection-decision-tree" aria-label="Permalink to &quot;Selection Decision Tree&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>START: Incoming request with tokens estimate</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌─ Is this FAST task (50-500 tokens)?</span></span>
<span class="line"><span>│  ├─ YES → Check latency SLA</span></span>
<span class="line"><span>│  │  ├─ &lt;1s required? → Gemini 3 Flash (best speed, meets perf)</span></span>
<span class="line"><span>│  │  ├─ &lt;5s required? → Claude Haiku (fast enough, better quality reserve)</span></span>
<span class="line"><span>│  │  └─ Cost critical? → GPT-4o mini (emergency fallback)</span></span>
<span class="line"><span>│  │</span></span>
<span class="line"><span>│  └─ NO → Check tokens</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Is this NORMAL task (500-3K tokens)?</span></span>
<span class="line"><span>│  ├─ YES → Default to Claude Haiku (73% quality, $0.02/call typical, 5-20s OK)</span></span>
<span class="line"><span>│  └─ NO → Check complexity next</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Is this COMPLEX task (3K-10K tokens)?</span></span>
<span class="line"><span>│  ├─ YES → Check if multi-step reasoning required</span></span>
<span class="line"><span>│  │  ├─ Complex logic? → Claude Sonnet 4.5 (77% quality, $0.10/call typical)</span></span>
<span class="line"><span>│  │  ├─ Simple? → Claude Haiku (cost savings, still adequate)</span></span>
<span class="line"><span>│  │  └─ Cost critical? → Minimax M2.5 (80% quality, $0.01/call)</span></span>
<span class="line"><span>│  │</span></span>
<span class="line"><span>│  └─ NO → Check tokens again</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ Is this HIGH_COMPLEX task (&gt;10K tokens)?</span></span>
<span class="line"><span>   ├─ YES → Mission-critical?</span></span>
<span class="line"><span>   │  ├─ YES → Claude Opus 4.6 (81% quality, $0.50+/call, best reasoning)</span></span>
<span class="line"><span>   │  ├─ NO → Claude Sonnet 4.5 (77% quality, 3x cheaper than Opus)</span></span>
<span class="line"><span>   │  └─ NOT URGENT? → Minimax M2.5 (batch mode, $0.01/call)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   └─ NO → Should not reach here; escalate to human review</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br></div></div><hr><h2 id="cumulative-cost-projection-user-scenario" tabindex="-1">Cumulative Cost Projection (User Scenario) <a class="header-anchor" href="#cumulative-cost-projection-user-scenario" aria-label="Permalink to &quot;Cumulative Cost Projection (User Scenario)&quot;">​</a></h2><p><strong>Current state:</strong> ~$550/mo across all providers</p><p><strong>Optimized allocation:</strong></p><table tabindex="0"><thead><tr><th>Category</th><th>Monthly Budget</th><th>Models</th><th>Rationale</th></tr></thead><tbody><tr><td>FAST (25% of requests)</td><td>$50</td><td>Gemini Flash primary, Haiku fallback</td><td>Latency-critical, high-volume</td></tr><tr><td>NORMAL (50% of requests)</td><td>$150</td><td>Claude Haiku primary (70-80% of this category), Gemini fallback</td><td>Default tier, volume driver</td></tr><tr><td>COMPLEX (20% of requests)</td><td>$120</td><td>Claude Sonnet (60% of this), Haiku (40% of this)</td><td>Reasoning tier, selective use</td></tr><tr><td>HIGH_COMPLEX (5% of requests)</td><td>$80</td><td>Claude Opus (70% of this), Sonnet (30% of this)</td><td>Mission-critical only</td></tr><tr><td><strong>Contingency</strong></td><td>$50</td><td>Emergency fallback (GPT-4o mini, unused Gemini credits)</td><td>Buffer for overages</td></tr><tr><td><strong>TOTAL</strong></td><td><strong>$450</strong></td><td>—</td><td><strong>$100/mo savings vs. current</strong></td></tr></tbody></table><hr><h2 id="notes-caveats" tabindex="-1">Notes &amp; Caveats <a class="header-anchor" href="#notes-caveats" aria-label="Permalink to &quot;Notes &amp; Caveats&quot;">​</a></h2><ol><li><strong>Benchmarks are point-in-time.</strong> SWE-Bench, AIME, and other metrics evolve quarterly. Re-evaluate Q1 2026.</li><li><strong>Latency varies by load.</strong> P50/P99 timings assume normal load; peak times may add 500ms-1s.</li><li><strong>Cost includes token tax.</strong> Estimates assume input:output ratio of 1:1. Complex reasoning (o1 family) may have higher output multipliers.</li><li><strong>Quality is task-dependent.</strong> A model&#39;s benchmark score doesn&#39;t guarantee performance on your specific workload. Use shadow testing before full commit.</li><li><strong>Cursor Ultra credit model.</strong> $20/mo subscription = $0.50/M effective, but $600-1000/mo overages. Use as supplementary, not primary.</li><li><strong>Gemini Flash constraints.</strong> Requires Google Cloud account; some features (video, advanced tools) are premium.</li><li><strong>Minimax M2.5 production readiness.</strong> Strong benchmarks; lower production track record in US market. Recommend shadow testing before critical path.</li></ol><hr><h2 id="quick-reference-i-have-1-minute-what-should-i-use" tabindex="-1">Quick Reference: &quot;I have 1 minute, what should I use?&quot; <a class="header-anchor" href="#quick-reference-i-have-1-minute-what-should-i-use" aria-label="Permalink to &quot;Quick Reference: &quot;I have 1 minute, what should I use?&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Model</th><th>Why</th></tr></thead><tbody><tr><td>Quick fix, low stakes</td><td>Claude Haiku</td><td>Best overall ratio; 73% is good enough</td></tr><tr><td>API integration test</td><td>Gemini 3 Flash</td><td>Fastest, meets 78% quality bar</td></tr><tr><td>Architecture decision</td><td>Claude Opus 4.6</td><td>81% quality + best reasoning for novel problems</td></tr><tr><td>Urgent, no budget left</td><td>GPT-4o mini</td><td>Meets 70% floor; ultra-cheap</td></tr><tr><td>Agentic loop, 1000+ calls/mo</td><td>Minimax M2.5</td><td>Frontier quality at ultra-low cost</td></tr><tr><td>Stuck with medium problem</td><td>Claude Sonnet 4.5</td><td>77% quality, faster than Opus, worth the cost</td></tr></tbody></table><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>`,47)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
